#!/usr/bin/env python3
"""
Generate port/include/embedded_fonts.h for the self-contained demos.

Reads the ground-truth font-usage capture (FONTDUMP lines produced by the
instrumented precalc run), resolves each used (family, bold, italic) face to a
real .ttf on the host (or a synth-oblique base), subsets each file to exactly the
glyphs it must render with pyftsubset, and emits one C header containing the
subsetted font bytes plus a name-based resolver.

Faithfulness notes:
  - Tahoma / Impact have no real italic file (Windows GDI synthesized it), so
    italic for those is the upright file + a shear flag (renderer slants it).
  - Fixedsys has no TrueType at all; substitute Courier New regular (used for a
    single glyph 'O' in ProjectGenesis).

Re-run after changing the demos' text: it is a build-time step, the generated
header is committed so the build itself needs no fonttools.
"""
import re, subprocess, sys, os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
SUBSET_DIR = os.path.join(HERE, "subset")
OUT_HEADER = os.path.join(ROOT, "port", "include", "embedded_fonts.h")
DUMPS = {"APCU": "/tmp/apcu.out", "ProjectGenesis": "/tmp/pg.out", "ChaosTheory": "/tmp/ct.out"}

# Families whose italic/bold are real separate files (no synthesis).
REAL_STYLE_FAMS = {"Arial", "Times New Roman", "Verdana", "Courier New", "Trebuchet MS"}
SYNTH_ITALIC_FAMS = {"Tahoma", "Impact"}     # real upright only; italic = shear

pat = re.compile(r'FONTDUMP font=(.*) bold=(\d+) italic=(\d+) size=(\d+) text=\[(.*)\]$')

def fc_file(family, bold, ital):
    w = 200 if bold else 80
    s = 100 if ital else 0
    out = subprocess.check_output(
        ["fc-match", "-f", "%{file}", f"{family}:weight={w}:slant={s}"]).decode()
    return out.strip()

def resolve(family, bold, ital):
    """(real_ttf_path, shear_flag) for a used face."""
    if family == "Fixedsys":
        return fc_file("Courier New", 0, 0), 0          # substitute mono
    if family in SYNTH_ITALIC_FAMS:
        return fc_file(family, bold, 0), (1 if ital else 0)  # upright file + shear
    return fc_file(family, bold, ital), 0               # real per-style file

# 1. collect used faces -> codepoints (unioned across demos)
faces = {}   # (family,bold,ital) -> set(codepoints)
for fn in DUMPS.values():
    for line in open(fn, encoding="latin1"):
        m = pat.match(line.rstrip("\n"))
        if not m:
            continue
        fam, bold, ital, _size, text = m.group(1), int(m.group(2)), int(m.group(3)), m.group(4), m.group(5)
        faces.setdefault((fam, bold, ital), set()).update(ord(c) for c in text)

# 2. resolve faces -> files; union codepoints per file; remember (face -> file,shear)
file_cps = {}        # ttf_path -> set(codepoints)
face_file = {}       # (family,bold,ital) -> (ttf_path, shear)
for (fam, bold, ital), cps in faces.items():
    path, shear = resolve(fam, bold, ital)
    face_file[(fam, bold, ital)] = (path, shear)
    file_cps.setdefault(path, set()).update(cps)
    file_cps[path].add(0x20)   # always keep space

# 3. subset each file, read bytes, assign a C var name
def varname(path):
    base = os.path.splitext(os.path.basename(path))[0]
    return "font_" + re.sub(r'[^0-9a-zA-Z_]', '_', base)

file_var = {}
file_bytes = {}
os.makedirs(SUBSET_DIR, exist_ok=True)
for path, cps in sorted(file_cps.items()):
    var = varname(path)
    out = os.path.join(SUBSET_DIR, var + ".ttf")
    unis = ",".join("U+%04X" % c for c in sorted(cps))
    subprocess.check_call(["pyftsubset", path, "--unicodes=" + unis,
                           "--output-file=" + out, "--no-hinting",
                           "--notdef-outline", "--desubroutinize"])
    file_var[path] = var
    file_bytes[var] = open(out, "rb").read()
    print(f"  {os.path.basename(path):<16} {len(cps):3d} glyphs -> {len(file_bytes[var]):6d} bytes  ({var})")

# 4. emit the header
def c_array(name, data):
    out = [f"static const unsigned char {name}[] = {{"]
    for i in range(0, len(data), 16):
        out.append("  " + ",".join(str(b) for b in data[i:i+16]) + ",")
    out.append("};")
    return "\n".join(out)

lines = ["/* GENERATED by third_party/fonts/gen_embedded_fonts.py - do not edit. */",
         "#ifndef EMBEDDED_FONTS_H", "#define EMBEDDED_FONTS_H", "#include <string.h>", ""]
for var in sorted(file_bytes):
    lines.append(c_array(var, file_bytes[var]))
    lines.append("")

lines += ["typedef struct { const char *family; int bold, italic;",
          "                 const unsigned char *data; unsigned int len; int shear; } EmbeddedFace;",
          "", "static const EmbeddedFace g_embedded_faces[] = {"]
# Arial regular first so it is the global fallback (g_embedded_faces[0]).
def sort_key(k):
    fam, b, i = k
    return (fam != "Arial", b, i, fam)
for (fam, bold, ital) in sorted(face_file, key=sort_key):
    path, shear = face_file[(fam, bold, ital)]
    var = file_var[path]
    lines.append(f'  {{"{fam}", {bold}, {ital}, {var}, sizeof({var}), {shear}}},')
lines += ["};", "",
    "static const EmbeddedFace *find_embedded_face(const char *family, int bold, int italic) {",
    "  unsigned i; const EmbeddedFace *reg = 0;",
    "  for (i = 0; i < sizeof(g_embedded_faces)/sizeof(g_embedded_faces[0]); i++) {",
    "    const EmbeddedFace *f = &g_embedded_faces[i];",
    "    if (!strcmp(f->family, family)) {",
    "      if (f->bold == bold && f->italic == italic) return f;",
    "      if (f->bold == 0 && f->italic == 0) reg = f;",
    "    }",
    "  }",
    "  if (reg) return reg;",
    "  return &g_embedded_faces[0];",
    "}",
    "#endif"]

os.makedirs(os.path.dirname(OUT_HEADER), exist_ok=True)
open(OUT_HEADER, "w").write("\n".join(lines) + "\n")
total = sum(len(b) for b in file_bytes.values())
print(f"\n{len(file_bytes)} subset fonts, {total} bytes total -> {OUT_HEADER}")
